package cn.yueji.balance;

import android.view.*;
import android.widget.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.uiautomator.*;
import org.junit.*;
import org.junit.runner.RunWith;
import java.time.*;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public class V4711UiTest {
    final V470UiTest old=new V470UiTest();final YuejiTest t=old.t;final V43UiTest h=old.h;
    @Before public void before(){old.before();t.context.getSharedPreferences("updates",0).edit().putString("guideRead",UsageGuideActivity.REVISION).putLong("lastOpenedBuild",31).commit();}
    @After public void after()throws Exception{old.after();}
    Ledger.Data sample(){return new V4711Fixture().data();}
    static final class V4711Fixture {
        Ledger.Data data(){Ledger.Data d=new Ledger.Data();d.settings.autoRefresh=false;for(int i=1;i<=2;i++){Ledger.Account a=new Ledger.Account(i,i==1?"支付宝":"微信",i==1?"支付宝":"微信");a.created=LocalDateTime.of(2026,9,30,20,0);a.opening=i==1?1000000:500000;d.accounts.add(a);MonthLedger.updateAccount(d,a.id,a.created,a.opening);}return d;}
    }
    void history(long id){t.ui(()->{t.app.accountId=id;t.app.go("account_history");});}
    void form(String kind,String amount,int account,boolean checked,LocalDateTime at){t.ui(()->{t.app.openEntry(kind,null);if(!Ledger.INCOME.equals(kind))((EditText)h.desc(t.app.body,"名称")).setText("房租");((EditText)h.desc(t.app.body,"金额")).setText(amount);((Spinner)h.desc(t.app.body,"账户（可选，勾选后必选）")).setSelection(account);((CheckBox)h.desc(t.app.body,"是否计入账户收支")).setChecked(checked);MainActivity.DateControl date=(MainActivity.DateControl)h.desc(t.app.body,(Ledger.INCOME.equals(kind)?"到账时间":"支出时间")+"日期").getTag();date.at=at;date.update();});}
    void save(){t.ui(()->t.findText(t.app.body,"保存记录").performClick());}
    @Test public void transferAndUpdateAreTogetherBelowAccountName(){t.start(sample());history(1);t.device.waitForIdle();t.ui(()->{View transfer=t.findText(t.app.body,"转账"),update=t.findText(t.app.body,"更新余额"),name=t.findText(t.app.body,"支付宝 · 支付宝");assertNotNull(transfer);assertSame(transfer.getParent(),update.getParent());int[] pos=new int[2],namePos=new int[2];transfer.getLocationOnScreen(pos);name.getLocationOnScreen(namePos);assertTrue(pos[1]>=namePos[1]+name.getHeight());assertEquals(transfer.getWidth(),update.getWidth(),2);});old.shot("v4711-account-actions.png");}
    @Test public void transferDialogUpdatesBothAccountsAndSourcesAtomically(){t.start(sample());history(1);t.ui(()->t.findText(t.app.body,"转账").performClick());t.device.wait(Until.findObject(By.desc("转入账户")),2000).click();old.tap("微信");t.device.findObject(By.desc("转账金额")).setText("1500");old.tap("保存转账");Ledger.Data saved=t.store.load();assertEquals(1,saved.transfers.size());assertEquals(850000,saved.balance(saved.accounts.get(0)));assertEquals(650000,saved.balance(saved.accounts.get(1)));assertEquals(1500000,saved.total());assertTrue(saved.entries.isEmpty());Ledger.Transfer transfer=saved.transfers.get(0);for(AccountCash.Flow flow:AccountCash.flows(saved))assertTrue(flow.source.contains("支付宝向微信转账1500.00元"));assertEquals(1,saved.snapshots.size());history(2);assertNotNull(t.device.wait(Until.findObject(By.textContains("支付宝向微信转账1500.00元")),2000));old.shot("v4711-transfer-both-sides.png");}
    @Test public void transferCancelAndMissingAccountDoNotSave(){t.start(sample());history(1);String before=t.store.exportJson();t.ui(()->t.findText(t.app.body,"转账").performClick());t.device.findObject(By.desc("转账金额")).setText("1500");old.tap("保存转账");assertNotNull(t.device.wait(Until.findObject(By.textContains("请选择转出和转入账户")),2000));assertEquals(before,t.store.exportJson());old.tap("知道了");old.tap("取消");assertEquals(before,t.store.exportJson());}
    @Test public void transferManagementDeleteRemovesBothDerivedSides(){Ledger.Data d=sample();TransferLedger.save(d,0,1,2,150000,LocalDateTime.of(2026,10,5,15,0),"");t.start(d);t.ui(()->{t.app.accountId=1;t.app.go("account_transfers");h.first(t.app.body,SwipeRow.class).openUp();});old.tap("删除");old.tap("删除");Ledger.Data saved=t.store.load();assertTrue(saved.transfers.isEmpty());assertEquals(1000000,saved.balance(saved.accounts.get(0)));assertEquals(500000,saved.balance(saved.accounts.get(1)));}
    @Test public void manualBalanceNoteHasDefaultAndSupportsCustomText(){t.start(sample());history(1);t.ui(()->t.findText(t.app.body,"更新余额").performClick());assertEquals("用户手动更新余额",t.device.wait(Until.findObject(By.desc("余额备注")),2000).getText());t.device.findObject(By.desc("本账户余额")).setText("9000");old.tap("保存");Ledger.Data saved=t.store.load();Ledger.Snapshot latest=saved.latest();assertEquals("用户手动更新余额",latest.notes.get(1L));t.ui(()->t.app.updateAccountBalance(t.app.focusedAccount(),t.app.data.latest()));t.device.findObject(By.desc("余额备注")).setText("对照银行卡核对");old.tap("保存");assertEquals("对照银行卡核对",t.store.load().latest().notes.get(1L));old.shot("v4711-manual-note.png");}
    @Test public void uncheckedIncomeCanSaveWithoutAccountOrBalanceMutation(){Ledger.Data d=sample();t.start(d);form(Ledger.INCOME,"1500",0,false,LocalDateTime.of(2026,10,5,15,0));save();Ledger.Data saved=t.store.load();assertEquals(1,saved.entries.size());assertFalse(saved.entries.get(0).cashLinked);assertEquals(0,saved.entries.get(0).accountId);assertEquals(1,saved.snapshots.size());assertEquals(1500000,saved.total());}
    @Test public void checkedIncomeRequiresAccountAndRetainsDraftOnError(){t.start(sample());String before=t.store.exportJson();form(Ledger.INCOME,"1500",0,true,LocalDateTime.of(2026,10,5,15,0));save();assertNotNull(t.device.wait(Until.findObject(By.textContains("必须选择账户")),2000));assertEquals(before,t.store.exportJson());old.tap("知道了");t.ui(()->{assertEquals("1500",((EditText)h.desc(t.app.body,"金额")).getText().toString());assertTrue(((CheckBox)h.desc(t.app.body,"是否计入账户收支")).isChecked());});}
    @Test public void checkedIncomeGeneratesCreditedSourceBalance(){t.start(sample());form(Ledger.INCOME,"1500",1,true,LocalDateTime.of(2026,10,5,15,0));save();Ledger.Data saved=t.store.load();assertEquals(1150000,saved.balance(saved.accounts.get(0)));assertEquals(0,Ledger.month(saved,YearMonth.of(2026,10)).expense);assertTrue(saved.entries.get(0).nearestCash);assertTrue(AccountCash.flows(saved).get(0).source.contains("收入 ·"));assertEquals(1,saved.snapshots.size());}
    @Test public void checkedHistoricalExpenseUsesFutureRealAnchorWithoutDoubleDebit(){Ledger.Data d=sample();MonthLedger.updateAccount(d,1,LocalDateTime.of(2026,10,21,10,0),900000);MonthLedger.updateAccount(d,1,LocalDateTime.of(2026,10,31,20,0),500000);t.start(d);form(Ledger.LARGE,"1500",1,true,LocalDateTime.of(2026,10,30,10,0));save();Ledger.Data saved=t.store.load();assertEquals(3,saved.snapshots.size());assertEquals(-150000,AccountCash.flows(saved).get(0).delta);assertEquals(500000,saved.balance(saved.accounts.get(0)));history(1);old.shot("v4711-nearest-historical-expense.png");}
    @Test public void uncheckedExpenseIsDetailsOnlyAndPolicySitsAboveSave(){t.start(sample());form(Ledger.LARGE,"1500",0,false,LocalDateTime.of(2026,10,5,15,0));t.device.waitForIdle();t.ui(()->{View checkbox=h.desc(t.app.body,"是否计入账户收支"),save=t.findText(t.app.body,"保存记录");int[] a=new int[2],b=new int[2];checkbox.getLocationInWindow(a);save.getLocationInWindow(b);assertTrue(a[1]+checkbox.getHeight()<=b[1]);});old.shot("v4711-opt-in-expense-form.png");save();assertEquals(1,t.store.load().entries.size());assertEquals(1,t.store.load().snapshots.size());}
    @Test public void checkboxAndSelectionSurviveFormDraftRestore(){t.start(sample());form(Ledger.INCOME,"1500",2,true,LocalDateTime.of(2026,10,5,15,0));t.ui(()->{FormDraft draft=new FormDraft();draft.capture(t.app.body);((CheckBox)h.desc(t.app.body,"是否计入账户收支")).setChecked(false);((Spinner)h.desc(t.app.body,"账户（可选，勾选后必选）")).setSelection(0);draft.restore(t.app.body);assertTrue(((CheckBox)h.desc(t.app.body,"是否计入账户收支")).isChecked());assertEquals(2,((Spinner)h.desc(t.app.body,"账户（可选，勾选后必选）")).getSelectedItemPosition());});}
    @Test public void checkboxAndAccountSurviveActivityRecreation(){t.start(sample());form(Ledger.INCOME,"1500",2,true,LocalDateTime.of(2026,10,5,15,0));android.app.Instrumentation.ActivityMonitor monitor=t.instrument.addMonitor(MainActivity.class.getName(),null,false);t.ui(()->t.app.recreate());MainActivity recreated=(MainActivity)monitor.waitForActivityWithTimeout(4000);assertNotNull(recreated);t.app=recreated;t.instrument.waitForIdleSync();t.ui(()->{assertTrue(((CheckBox)h.desc(t.app.body,"是否计入账户收支")).isChecked());assertEquals(2,((Spinner)h.desc(t.app.body,"账户（可选，勾选后必选）")).getSelectedItemPosition());assertEquals("1500",((EditText)h.desc(t.app.body,"金额")).getText().toString());});t.instrument.removeMonitor(monitor);}
    @Test public void trendPolicyAndMonthlyBoundaryExplanationAreAvailable(){Ledger.Data d=sample();MonthLedger.updateAccount(d,1,LocalDateTime.of(2026,10,31,20,0),700000);t.start(d);t.ui(()->{t.app.assetTab=1;t.app.render();h.desc(t.app.body,"资产变动趋势说明").performClick();});assertNotNull(t.device.wait(Until.findObject(By.textContains("折线仅供参考")),2000));old.shot("v4711-trend-warning.png");t.device.pressBack();t.ui(()->{t.app.monthFocus=YearMonth.of(2026,10);t.app.go("month_detail");h.desc(t.app.body,"月支出口径说明").performClick();});assertNotNull(t.device.wait(Until.findObject(By.textContains("上月末最后余额")),2000));old.shot("v4711-month-boundary-warning.png");}
    @Test public void incomeAndExpenseDetailsExplainOptionalAccountPolicy(){t.start(sample());for(String page:new String[]{"income_detail","large_detail"}){t.ui(()->{t.app.go(page);h.desc(t.app.body,page.equals("income_detail")?"全部收入说明":"大宗支出明细说明").performClick();});assertNotNull(t.device.wait(Until.findObject(By.textContains("不勾选：仅存明细")),2000));t.device.pressBack();}}
    @Test public void newControlsFitShortScreenLargeFontAndDarkMode()throws Exception{try{t.device.executeShellCommand("wm size 1080x1920");t.device.executeShellCommand("wm density 420");t.device.executeShellCommand("settings put system font_scale 1.3");t.start(sample());t.ui(()->{t.app.getPreferences(0).edit().putInt("appearance",2).commit();t.app.render();});history(1);old.shot("v4711-dark-large-font-actions.png");t.ui(()->t.findText(t.app.body,"转账").performClick());assertNotNull(t.device.wait(Until.findObject(By.text("保存转账")),2000));old.shot("v4711-dark-large-font-transfer.png");old.tap("取消");form(Ledger.INCOME,"1500",1,true,LocalDateTime.of(2026,10,5,15,0));t.ui(()->((ScrollView)t.app.body.getParent()).fullScroll(View.FOCUS_DOWN));assertNotNull(t.device.wait(Until.findObject(By.text("是/否计入账户收支")),2000));old.shot("v4711-dark-large-font-checkbox.png");}finally{t.device.executeShellCommand("wm size reset");t.device.executeShellCommand("wm density reset");t.device.executeShellCommand("settings put system font_scale 1.0");}}
}
